```c
#include <DHT.h>

// Define the pin connected to the DHT22 sensor (usually digital pin 2)
#define DHT_PIN 2

// Define the calibration values ( default values for DHT22 )
const float calibrationTemp[] = {0.96, 0.96}; // temperature calibration coefficients (alpha, beta)
const float calibrationHum[] = {0.98, 0.98}; // humidity calibration coefficients (alpha, beta)

// Define the sensor object
DHT myDHT(DHT_PIN, DHT22);

void setup() {
  Serial.begin(9600);
  myDHT.begin();
}

void loop() {
  // Read temperature and humidity values from the sensor
  float temperature = myDHT.readTemperature();
  float humidity = myDHT.readHumidity();

  // Apply calibration to the readings
  float calibratedTemp = applyCalibration(temperature, calibrationTemp[0], calibrationTemp[1]);
  float calibratedHum = applyCalibration(humidity, calibrationHum[0], calibrationHum[1]);

  // Print the calibrated values to the serial monitor
  Serial.print("Calibrated Temperature: ");
  Serial.print(calibratedTemp);
  Serial.print("°C");
  Serial.println();

  Serial.print("Calibrated Humidity: ");
  Serial.print(calibratedHum);
  Serial.print("%");
  Serial.println();

  delay(2000); // wait for 2 seconds before taking the next reading
}

// Function to apply calibration to the sensor readings
float applyCalibration(float reading, float alpha, float beta) {
  return (reading - beta) / alpha;
}
```
