    return acc;
  }, []).map((group) => ({ ...group, logs: group.logs.map((l) => ({ ...l, hidden: group.hidden })) }));

  return groupLogs;
};

const getLogType = (log: BuildLog): FilterState => {
  return log.error ? 'errors' : log.warning ? 'warnings' : 'all';
};
