import { createContext, useState } from 'react';

const FeedbackFormContext = createContext();

const FeedbackFormProvider = ({ children }) => {
  const [feedbackForm, setFeedbackForm] = useState({
    questions: [
      { id: 1, text: 'How was your overall experience?' },
      { id: 2, text: 'How would you rate the instructor?' },
      { id: 3, text: 'How would you rate the course materials?' },
    ],
    answers: {},
  });

  const handleAnswerSubmit = (id, answer) => {
    setFeedbackForm((prevForm) => {
      const newForm = { ...prevForm };
      newForm.answers[id] = answer;
      return newForm;
    });
  };

  return (
    <FeedbackFormContext.Provider value={{ feedbackForm, handleAnswerSubmit }}>
      {children}
    </FeedbackFormContext.Provider>
  );
};

export { FeedbackFormProvider, FeedbackFormContext };
```
