import { FeedbackFormContext } from './FeedbackFormContext';

const FeedbackForm = () => {
  const { feedbackForm, handleAnswerSubmit } = useContext(FeedbackFormContext);

  return (
    <form>
      {feedbackForm.questions.map((question, index) => (
        <div key={question.id}>
          <label>{question.text}</label>
          <input
