const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
const initialAngle = document.getElementById('initial-angle');
const releaseButton = document.getElementById('release-button');
let then = 0;
let angle = 0;
let velocity = 0;
let gravity = 9.81;

releaseButton.addEventListener('click', () => {
    angle = Math.PI * initialAngle.value / 180;
    velocity = 0;
    then = performance.now();
});

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(200, 200, 50,angle - Math.PI/2, angle + Math.PI/2);
    ctx.stroke();

    const now = performance.now();
    const deltaTime = (now - then) / 1000;
    then = now;

    velocity += -gravity * deltaTime;
    angle += velocity * deltaTime;

    if (Math.abs(velocity) < 0.01) {
        velocity = 0;
        angle = 0;
    }

    requestAnimationFrame(draw);
}

draw();
```

This script assumes that the initial angle is in degrees and converts it to radians by multiplying by `Math.PI / 180`. The pendulum starts at rest and acceleration towards the ground is constant due to gravity. The velocity and angle are updated every frame based on the previous values. The pendulum's position is calculated using trigonometry and updated based on the current angle. When the velocity becomes very small, it is considered to be at rest, and the animation stops.

