func handler(ctx context.Context, svc ec2.EC2) error {
	// Set the region from the AWS Lambda environment
	region := aws.String(os.Getenv("AWS_REGION"))

	// Create a DynamoDB table name for storing snapshot tags
	tableName := "snaps"

	// Create a DynamoDB session
	dynamoSvc := ec2.New(session.New(), &aws.Config{Region: region})

	// Get a list of EBS snapshots
	input := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("status"),
				Values: []*string{
					aws.String("completed"),
				},
			},
		},
	}
	snapshots, err := svc_DescribeSnapshots(input)
	if err != nil {
		return err
	}

	// Filter snapshots by 'backup_type' tag
	var monthly, daily, weekly, yearly []*ec2.Snapshot
	for _, snap := range snapshots.Snapshots {
		tagValue, err := getTagValue(snap, "backup_type")
		if err != nil {
			return err
		}
		switch *tagValue {
		case "monthly":
			monthly = append(monthly, snap)
		case "daily":
			daily = append(daily, snap)
		case "weekly":
			weekly = append(weekly, snap)
		case "yearly":
			yearly = append(yearly, snap)
		}
	}

	// Delete snapshots based on retention policy
	for _, snap := range monthly {
		if len(monthly) > 14 {
			err := svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(snap.SnapshotId),
			})
			if err != nil {
				return err
			}
		}
	}
	for _, snap := range daily {
		if len(daily) > 10 {
			err := svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(snap.SnapshotId),
			})
			if err != nil {
				return err
			}
		}
	}
	for _, snap := range weekly {
		if len(weekly) > 4 {
			err := svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(snap.SnapshotId),
			})
			if err != nil {
				return err
			}
		}
	}
	if len(yearly) > 1 {
		err := svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
			SnapshotId: aws.String(yearly[0].SnapshotId),
		})
		if err != nil {
			return err
		}
	}

	return nil
}

func getTagValue(snap *ec2.Snapshot, key string) (*string, error) {
	input := &ec2.GetTagsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("resource-id"),
				Values: []*string{
					aws.String(snap.SnapshotId),
				},
			},
			{
				Name: aws.String("key"),
				Values: []*string{
					aws.String(key),
				},
			},
		},
	}
	tags, err := ec2.GetTags(input)
	if err != nil {
		return nil, err
	}
	for _, tag := range tags.TagSet {
		if *tag.Key == key {
			return tag.Value, nil
		}
	}
	return nil, fmt.Errorf("tag %s not found", key)
}

