import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.data.mongodb.core.query.Update;
import org.springframework.data.mongodb.core.query.Query.EvaluationContext;

public class MongoDBQueryTranslator extends AbstractMongoQueryTranslator {

    @Override
    public Query convert(String query) {
        Query mongoQuery = new Query();
        String[] queryParts = query.split(" ");
        for (int i = 0; i < queryParts.length; i++) {
            String part = queryParts[i];
            if (part.startsWith("SELECT")) {
                String[] columns = part.split("=")[1].split(",");
                for (String column : columns) {
                    mongoQuery.fields().include(column.trim());
                }
            } else if (part.startsWith("FROM")) {
                String tableName = part.split("=")[1].trim();
                mongoQuery.collection(tableName);
            } else if (part.startsWith("WHERE")) {
                if (part.contains("AND")) {
                    String[] conditions = part.split("AND");
                    for (String condition : conditions) {
                        mongoQuery.addCriteria(convertCondition(condition));
                    }
                } else if (part.contains("OR")) {
                    String[] conditions = part.split("OR");
                    for (String condition : conditions) {
                        mongoQuery.addCriteria(convertCondition(condition));
                    }
                } else {
                    mongoQuery.addCriteria(convertCondition(part));
                }
            } else if (part.startsWith("UPDATE")) {
                String[] updateParts = part.split("SET");
                String tableName = updateParts[0].split("=")[1].trim();
                Query updateQuery = new Query().addCriteria(convertCondition(tableName));
                String updateString = updateParts[1].trim();
                Update update = new Update();
                String[] updates = updateString.split(",");
                for (String updatePart : updates) {
                    String[] updateColumns = updatePart.split("=");
                    update.set(updateColumns[0].trim(), updateColumns[1].trim());
                }
                mongoDB.update(updateQuery, update);
            } else if (part.startsWith("INSERT")) {
                String[] insertParts = part.split("VALUES");
                String tableName = insertParts[0].split("=")[1].trim();
                Query insertQuery = new Query().addCriteria(convertCondition(tableName));
                String valuesString = insertParts[1].trim();
                String[] values = valuesString.split(",");
                String[] queryPartsNew = new String[values.length * 2];
                for (int j = 0; j < values.length; j++) {
                    queryPartsNew[j * 2] = "value";
                    queryPartsNew[j * 2 + 1] = values[j].trim();
                }
                mongoDB.insert(new Query().addCriteria(convertCondition(tableName)).createQuery(queryPartsNew));
            } else if (part.startsWith("DELETE")) {
                String[] deleteParts = part.split("WHERE");
                String tableName = deleteParts[0].split("=")[1].trim();
                Query deleteQuery = new Query().addCriteria(convertCondition(tableName));
                mongoDB.remove(deleteQuery);
            }
        }
        return mongoQuery;
    }

    private Criteria convertCondition(String condition) {
        Criteria criteria = new Criteria();
        if (condition.contains("=")) {
